// Synthetic independent field-writer inputs; FFmpeg8.0.1 fixed-integer PCM excerpts.
// Source/PCM hashes and command/build provenance: docs/MPEG1-LAYER2-VERIFICATION.md.
[TestClass]
public class Mpeg1LayerTwoReferenceTests
{
	[DataTestMethod]
	[DynamicData( nameof( References ), DynamicDataSourceType.Method )]
	public void IndependentGeneratedReferenceExcerptsStayWithinMeasuredOneLsb( string name, string frameBase64, string sourceSha, int rate, int channels, int[] indices, int[] expected )
	{
		var frame = Convert.FromBase64String( frameBase64 ); var data = Enumerable.Range( 0, 4 ).SelectMany( _ => frame ).ToArray();
		Assert.AreEqual( sourceSha, Convert.ToHexString( SHA256.HashData( data ) ).ToLowerInvariant() );
		var audio = Mp2Decoder.Decode( data ); Assert.AreEqual( rate, audio.SampleRate ); Assert.AreEqual( channels, audio.Channels ); Assert.AreEqual( 4, audio.FrameCount ); Assert.AreEqual( 4608 * channels, audio.Samples.Length ); Assert.AreEqual( 0, audio.TrailingBytes );
		for ( var i = 0; i < indices.Length; i++ ) Assert.IsTrue( Math.Abs( (int)audio.Samples[indices[i]] - expected[i] ) <= 1, $"{name} PCM[{indices[i]}={audio.Samples[indices[i]]}, fixed-integer reference{expected[i]}; measured1LSB envelope." );
	}
